// HRP expansion utilities (bech32-compatible behavior).
//
// bech32_hrp_expand(hrp) mirrors the Python reference:
//   [ord(x) >> 5 for x in hrp] + [0] + [ord(x) & 31 for x in hrp]

export function bech32HrpExpand(hrp) {
  const result = [];
  for (const ch of hrp) {
    result.push(ch.charCodeAt(0) >> 5);
  }
  result.push(0);
  for (const ch of hrp) {
    result.push(ch.charCodeAt(0) & 31);
  }
  return result;
}

