// BCH polymod checksum (bech32-compatible behavior).
//
// bech32_polymod(values) mirrors the Python reference implementation:
//   GEN = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3]
//   chk = 1
//   for v in values:
//       b = chk >> 25
//       chk = (chk & 0x1ffffff) << 5 ^ v
//       for i in range(5):
//           chk ^= GEN[i] if ((b >> i) & 1) else 0
//   return chk

const GEN = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3];

export function bech32Polymod(values) {
  let chk = 1;
  for (const v of values) {
    const b = chk >> 25;
    chk = ((chk & 0x1ffffff) << 5) ^ v;
    for (let i = 0; i < 5; i++) {
      if ((b >> i) & 1) {
        chk ^= GEN[i];
      }
    }
  }
  return chk;
}

