// Minimal command-line argument parser matching the Python argparse setup:
//   parser.add_argument("--a", type=str, required=True)
//   parser.add_argument("--b", type=str, required=True)
// Supports both "--key value" and "--key=value" forms.

export function parseArgs(argv, specs) {
  const values = {};
  const names = new Set(Object.keys(specs));

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];
    if (token.startsWith('--')) {
      let name;
      let value;
      const eq = token.indexOf('=');
      if (eq !== -1) {
        name = token.slice(2, eq);
        value = token.slice(eq + 1);
      } else {
        name = token.slice(2);
        value = argv[i + 1];
        i += 1;
      }
      if (names.has(name)) {
        values[name] = value;
      } else {
        console.error(`error: unrecognized arguments: --${name}`);
        process.exit(2);
      }
    } else {
      console.error(`error: unrecognized arguments: ${token}`);
      process.exit(2);
    }
  }

  for (const [name, spec] of Object.entries(specs)) {
    if (spec.required && values[name] === undefined) {
      console.error(`error: the following arguments are required: --${name}`);
      process.exit(2);
    }
    if (values[name] === undefined && 'default' in spec) {
      values[name] = spec.default;
    }
  }

  return values;
}

