import { parseArgs } from './lib/args.mjs';
import { bech32HrpExpand } from './lib/hrp.mjs';
import { bech32Polymod } from './lib/polymod.mjs';
import { formatPyList } from './lib/pyformat.mjs';

function main() {
  const args = parseArgs(process.argv.slice(2), {
    a: { required: true }, // HRP
    b: { required: true }, // Data as comma-separated integers
  });

  const data = args.b.split(',').map((s) => parseInt(s, 10));
  const hrpExpanded = bech32HrpExpand(args.a); // Expand HRP
  const combined = hrpExpanded.concat(data);
  const checksum = bech32Polymod(combined); // Compute polymod checksum
  console.log(formatPyList(hrpExpanded));
  console.log(checksum);
}

main();

